import{_ as e,o as a,c as i,ao as s}from"./chunks/framework.CrTfSnbh.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"GravityGeophysics.jl","tagline":"A software repository for gravity geophysics research and applications.","actions":[{"theme":"brand","text":"Getting Started","link":"/getting_started"},{"theme":"alt","text":"Run an inversion","link":"/inversion/running"},{"theme":"alt","text":"View on GitHub","link":"https://github.com/JuliaGeophysics/GravityGeophysics.jl"}]},"features":[{"title":"Forward modelling","details":"Closed-form gravity of rectangular prisms over any tensor mesh, with topography. A finite-difference Poisson solver comes along as an independent check.","link":"/forward"},{"title":"Two inversions, one workflow","details":"Gauss-Newton and a neural (INR) inversion share the same six input files, the same driver and the same result. Swap one control file to change method.","link":"/inversion/running"},{"title":"Meshes from your survey","details":"Point MakeMesh3D at a data file and it designs a padded mesh, a start model and a covariance around your stations.","link":"/data/mesh"},{"title":"Plots you can hand over","details":"Depth slices, cross-sections, observed-versus-predicted maps and convergence curves, written straight into the run folder.","link":"/plots"},{"title":"Worked examples","details":"Two synthetic surveys you can run end to end, with the true model shipped so you can score the result yourself.","link":"/examples"}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":null}'),r={name:"index.md"};function n(o,t,l,d,h,p){return a(),i("div",null,[...t[0]||(t[0]=[s('<h2 id="What-is-GravityGeophysics.jl?" tabindex="-1">What is GravityGeophysics.jl? <a class="header-anchor" href="#What-is-GravityGeophysics.jl?" aria-label="Permalink to &quot;What is GravityGeophysics.jl? {#What-is-GravityGeophysics.jl?}&quot;">​</a></h2><p>GravityGeophysics.jl does 3D forward modelling and inversion of gravity data for <strong>density contrast</strong>. It is part of the <a href="https://github.com/JuliaGeophysics" target="_blank" rel="noreferrer">JuliaGeophysics ecosystem</a> and is driven entirely by small plain-text files: a <code>.xyz</code> survey, block-layout <code>.den</code> models, <code>Key : value</code> control files, and a run folder written next to your data.</p><p>If you have a gravity survey and want a density model under it, you are in the right place.</p><h3 id="Two-ways-to-invert" tabindex="-1">Two ways to invert <a class="header-anchor" href="#Two-ways-to-invert" aria-label="Permalink to &quot;Two ways to invert {#Two-ways-to-invert}&quot;">​</a></h3><p>Both read the same files and return the same kind of result, so you can try one and then the other without changing anything else:</p><ul><li><p><strong>Gauss–Newton</strong> — the classical approach. Smallness and smoothing hold the model together, and sensitivity or depth weighting stops everything piling up at the surface.</p></li><li><p><strong>Implicit neural representation (INR)</strong> — a small coordinate network (<a href="https://github.com/LuxDL/Lux.jl" target="_blank" rel="noreferrer">Lux.jl</a>) outputs the density of every cell. There is no explicit regularizer; the network&#39;s limited capacity is what keeps the model smooth.</p></li></ul><p><a href="./inversion/choosing">Choosing between them</a> explains when each one tends to win.</p><h2 id="Install" tabindex="-1">Install <a class="header-anchor" href="#Install" aria-label="Permalink to &quot;Install {#Install}&quot;">​</a></h2><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;" class="repl-prompt repl-prompt-pkg">pkg</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;" class="repl-prompt repl-prompt-pkg">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> add GravityGeophysics</span></span></code></pre></div><p>You need Julia 1.13.0. Then head to <a href="./getting_started">Getting Started</a> to run your first forward model and inversion.</p><h2 id="Where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#Where-to-go-next" aria-label="Permalink to &quot;Where to go next {#Where-to-go-next}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">If you want to…</th><th style="text-align:right;">Read</th></tr></thead><tbody><tr><td style="text-align:right;">see it work in five minutes</td><td style="text-align:right;"><a href="./getting_started">Getting Started</a></td></tr><tr><td style="text-align:right;">understand the file formats</td><td style="text-align:right;"><a href="./data/files">Survey and model files</a></td></tr><tr><td style="text-align:right;">build a mesh around your stations</td><td style="text-align:right;"><a href="./data/mesh">Building a mesh</a></td></tr><tr><td style="text-align:right;">predict data from a model</td><td style="text-align:right;"><a href="./forward">Forward modelling</a></td></tr><tr><td style="text-align:right;">invert real data</td><td style="text-align:right;"><a href="./inversion/running">Running an inversion</a></td></tr><tr><td style="text-align:right;">make figures</td><td style="text-align:right;"><a href="./plots">Plots</a></td></tr><tr><td style="text-align:right;">see complete worked cases</td><td style="text-align:right;"><a href="./examples">Worked examples</a></td></tr></tbody></table>',12)])])}const u=e(r,[["render",n]]);export{c as __pageData,u as default};
